import { readFileSync } from "node:fs";
import { join } from "node:path";

let pkg = {};
try {
    pkg = JSON.parse(readFileSync(join(import.meta.dirname, "..", "package.json"), "utf-8"));
}
catch (e) {
    if (e.code !== "ENOENT")
        throw e;
}
const configName = pkg.appConfig?.name;
export const APP_NAME = configName || "app";
export const APP_TITLE = configName ? APP_NAME : "App";
export const CONFIG_DIR = pkg.appConfig?.configDir || ".config";
export const VERSION = pkg.version ?? "0.0.0";
export const RETRIES = pkg.appConfig?.retries ?? 3;
export const isBundled = typeof APP_BUNDLED !== "undefined" && APP_BUNDLED;
